package main
import("encoding/json";"os";"strings";"fmt";"go/ast";"go/parser";"go/token";"strconv";"github.com/d2lang/d2/d2compiler";"github.com/d2lang/d2/d2oracle";"github.com/d2lang/d2/d2format";"github.com/d2lang/util-go/mapfs")
type Input struct{Name string `json:"name"`; Source string `json:"source"`; Old string `json:"old_key"`; New string `json:"new_key"`; Desc bool `json:"include_descendants"`; Path string `json:"path,omitempty"`; Board []string `json:"board_path,omitempty"`; Files map[string]string `json:"files,omitempty"`; Expected string `json:"fixture_expected_source"`; ExpectedError string `json:"fixture_expected_error"`; Skip bool `json:"upstream_skip"`}
func str(e ast.Expr)string{if x,ok:=e.(*ast.BasicLit);ok&&x.Kind==token.STRING{s,err:=strconv.Unquote(x.Value);if err!=nil{panic(err)};return s};if x,ok:=e.(*ast.BinaryExpr);ok&&x.Op==token.ADD{return str(x.X)+str(x.Y)};panic(fmt.Sprintf("nonliteral string %T",e))}
func extract(path string)[]Input{file,err:=parser.ParseFile(token.NewFileSet(),path,nil,0);if err!=nil{panic(err)};rows:=[]Input{};for _,d:=range file.Decls{fn,ok:=d.(*ast.FuncDecl);if !ok||fn.Name.Name!="TestMove"{continue};ast.Inspect(fn.Body,func(n ast.Node)bool{assign,ok:=n.(*ast.AssignStmt);if !ok||len(assign.Lhs)!=1{return true};id,ok:=assign.Lhs[0].(*ast.Ident);if !ok||id.Name!="testCases"{return true};cases:=assign.Rhs[0].(*ast.CompositeLit);for _,e:=range cases.Elts{in:=Input{};for _,f:=range e.(*ast.CompositeLit).Elts{field:=f.(*ast.KeyValueExpr);name:=field.Key.(*ast.Ident).Name;switch name{case "name":in.Name=str(field.Value);case "text":in.Source=str(field.Value);case "key":in.Old=str(field.Value);case "newKey":in.New=str(field.Value);case "includeDescendants":in.Desc=field.Value.(*ast.Ident).Name=="true";case "skip":in.Skip=field.Value.(*ast.Ident).Name=="true";case "exp":in.Expected=str(field.Value);case "expErr":in.ExpectedError=str(field.Value);case "boardPath":for _,v:=range field.Value.(*ast.CompositeLit).Elts{in.Board=append(in.Board,str(v))};case "fsTexts":in.Files=map[string]string{};for _,v:=range field.Value.(*ast.CompositeLit).Elts{kv:=v.(*ast.KeyValueExpr);in.Files[str(kv.Key)]=str(kv.Value)}}};in.Name="upstream/"+in.Name;rows=append(rows,in)};return false})};return rows}
func main(){enc:=json.NewEncoder(os.Stdout);enc.SetIndent("","  ");if len(os.Args)>1{if err:=enc.Encode(extract(os.Args[1]));err!=nil{panic(err)};return};var inputs []Input;if err:=json.NewDecoder(os.Stdin).Decode(&inputs);err!=nil{panic(err)};rows:=[]any{};for _,in:=range inputs{func(){defer func(){if p:=recover();p!=nil{rows=append(rows,map[string]any{"input":in,"panic":fmt.Sprint(p)})}}();files:=map[string]string{};for k,v:=range in.Files{files[k]=v};entry:=in.Path;if entry==""{entry="input.d2"};files[entry]=in.Source;fs,err:=mapfs.New(files);if err!=nil{panic(err)};defer fs.Close();g,_,err:=d2compiler.Compile(entry,strings.NewReader(in.Source),&d2compiler.CompileOptions{FS:fs});out:="";if err==nil{g,err=d2oracle.Move(g,in.Board,in.Old,in.New,in.Desc);if err==nil{out=d2format.Format(g.AST)}};message:="";if err!=nil{message=err.Error()};rows=append(rows,map[string]any{"input":in,"source":out,"error":message})}()};if err:=enc.Encode(rows);err!=nil{panic(err)}}
